use vstd::prelude::*;

verus! {
    // Specification for the prefix sum function S(k)
    spec fn S(k: i8) -> i8
        requires
            k >= 0,
    {
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }

    // Function to solve the range queries
    fn solve(queries: Vec<(i8, i8)>) -> Vec<i8>
        requires
            queries.len() <= 128, // Since i8 can represent values from -128 to 127
        ensures
            result.len() == queries.len(),
            forall |i: usize| 0 <= i < queries.len() ==> 
                result[i] == S(queries[i].1) - S(queries[i].0 - 1),
    {
        let mut result: Vec<i8> = Vec::new();
        
        // Iterate over each query
        for (l, r) in queries.iter() {
            // Calculate the sum for the current query
            let sum = S(*r) - S(*l - 1);
            result.push(sum);
        }
        
        result
    }
}
